//! The bundled themes: every `themes/*.zon`, imported at comptime, so a
//! malformed palette is a compile error, not a runtime surprise. The
//! list is generated by `tools/theme_toml2zon.zig`; a new theme is a
//! new `.zon` beside these plus one line in `all`.
//!
//! This module is the `themes` import of the main module. It defines
//! the source shape itself because `src/` is not reachable from here
//! and a palette has no business knowing what mnml paints with it.

pub const Kind = enum { dark, light };

/// The shell prompt a terminal pane's shell may source
/// (`MNML_PROMPT_SCRIPT`, `src/app/pty_env.zig`): it reads the theme's
/// colours from the environment, which is why it lives with the themes.
pub const prompt_script = @embedFile("mnml-prompt.sh");

/// NvChad's `base_30`: the UI chrome colours, `0xrrggbb`. Every key is
/// optional because a few upstream palettes leave one out; the
/// derivation in `src/ui/theme.zig` has a fallback chain per role.
pub const Base30 = struct {
    white: ?u24 = null,
    darker_black: ?u24 = null,
    black: ?u24 = null,
    black2: ?u24 = null,
    one_bg: ?u24 = null,
    one_bg2: ?u24 = null,
    one_bg3: ?u24 = null,
    grey: ?u24 = null,
    grey_fg: ?u24 = null,
    grey_fg2: ?u24 = null,
    light_grey: ?u24 = null,
    red: ?u24 = null,
    baby_pink: ?u24 = null,
    pink: ?u24 = null,
    line: ?u24 = null,
    green: ?u24 = null,
    vibrant_green: ?u24 = null,
    nord_blue: ?u24 = null,
    blue: ?u24 = null,
    yellow: ?u24 = null,
    sun: ?u24 = null,
    purple: ?u24 = null,
    dark_purple: ?u24 = null,
    teal: ?u24 = null,
    orange: ?u24 = null,
    cyan: ?u24 = null,
    statusline_bg: ?u24 = null,
    lightbg: ?u24 = null,
    pmenu_bg: ?u24 = null,
    folder_bg: ?u24 = null,
    /// mnml's own: one colour per statusline segment, each falling back
    /// to the palette colour the segment wore before it had a key
    /// (`src/ui/theme.zig`, `Palette.seg`). No NvChad palette sets them.
    statusline_pr: ?u24 = null,
    statusline_symbol: ?u24 = null,
    statusline_find: ?u24 = null,
    statusline_jobs: ?u24 = null,
    statusline_codex: ?u24 = null,
    statusline_coverage: ?u24 = null,
    statusline_transfer: ?u24 = null,
    statusline_lsp: ?u24 = null,
    statusline_wrap: ?u24 = null,
    statusline_autosave: ?u24 = null,
    statusline_sel: ?u24 = null,
    statusline_workspace: ?u24 = null,
    statusline_language: ?u24 = null,
};

/// The syntax palette, `base00`..`base0F`. A missing slot falls back
/// to onedark's at load.
pub const Base16 = struct {
    base00: ?u24 = null,
    base01: ?u24 = null,
    base02: ?u24 = null,
    base03: ?u24 = null,
    base04: ?u24 = null,
    base05: ?u24 = null,
    base06: ?u24 = null,
    base07: ?u24 = null,
    base08: ?u24 = null,
    base09: ?u24 = null,
    base0A: ?u24 = null,
    base0B: ?u24 = null,
    base0C: ?u24 = null,
    base0D: ?u24 = null,
    base0E: ?u24 = null,
    base0F: ?u24 = null,
};

/// A key outside the schema, kept so the conversion loses nothing.
pub const Extra = struct { name: []const u8, hex: u24 };

pub const Source = struct {
    name: []const u8,
    kind: Kind,
    base_30: Base30 = .{},
    base_16: Base16 = .{},
    extra: []const Extra = &.{},
};

